def group_by_length_parity(strings):
    evens = []
    odds = []
    for s in strings:
        if len(s) % 2 == 0:
            evens.append(s)
        else:
            odds.append(s)
    return {'even_length': sorted(evens), 'odd_length': sorted(odds)}

def sort_tuples_by_sum_then_first(pairs):
