def is_balanced_ignoring_escapes(s):
    balance = 0
    idx = 0
    length = len(s)
    while idx < length:
        if s[idx] == "\\" and idx + 1 < length and s[idx + 1] in "()":
            idx += 2
            continue
        if s[idx] == "(":
            balance += 1
        elif s[idx] == ")":
            balance -= 1
            if balance < 0:
                return False
        idx += 1
    return balance == 0

