def longest_positive_run_sum(lst):
    best_sum = 0
    best_len = 0
    cur_sum = 0
    cur_len = 0
    for x in lst:
        if x > 0:
            cur_sum += x
            cur_len += 1
            if cur_len > best_len:
                best_len = cur_len
                best_sum = cur_sum
        else:
            cur_sum = 0
            cur_len = 0
    return best_sum

def age_in_years_months(birth, today):
    by, bm, bd = birth
    ty, tm, td = today
    total_months = (ty - by) * 12 + (tm - bm)
    if td < bd:
        total_months -= 1
    years, months = divmod(total_months, 12)
    return (years, months)
